def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]

    # Find the full-width horizontal barrier.
    barrier_r = None
    barrier_color = None
    for r, row in enumerate(grid):
        if row[0] != bg and all(x == row[0] for x in row):
            barrier_r, barrier_color = r, row[0]
            break

    out = [row[:] for row in grid]
    if barrier_r is None:
        return out

    cells = [(r, c) for r in range(h) for c in range(w)
             if grid[r][c] != bg and grid[r][c] != barrier_color]
    if not cells:
        return out

    min_r = min(r for r, _ in cells)
    max_r = max(r for r, _ in cells)

    if max_r < barrier_r:
        shift = barrier_r - 1 - max_r
        stripe_r = min_r + shift - 1
    else:
        shift = barrier_r + 1 - min_r
        stripe_r = max_r + shift + 1

    for r, c in cells:
        out[r][c] = bg
    for r, c in cells:
        nr = r + shift
        if 0 <= nr < h:
            out[nr][c] = grid[r][c]
    if 0 <= stripe_r < h:
        out[stripe_r] = [8] * w

    return out
